// TEP-62 NFT collection contract.
//
// This is the "factory" contract: it deploys and keeps track of
// individual NFT item contracts (see nft-item.tolk). Only its admin can
// mint new NFTs; anyone can read collection/item data.

import "errors";
import "storage";
import "messages";

// Deploys (= creates on-chain) one NFT item contract at its predictable
// address, and hands it its initial owner/content/royalty data in the
// same message (see nft-item.tolk's "not initialized" branch).
fun deployNftItem(
    itemIndex: uint64,
    nftItemCode: cell,
    attachGrams: coins,
    initParams: Cell<NftItemInitAtDeployment>,
) {
    val deployMsg = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: calcDeployedNftItem(
            itemIndex,
            contract.getAddress(),
            nftItemCode,
        ),
        value: attachGrams,
        body: initParams,
    });
    deployMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
}

type AllowedMessageToNftCollection =
    | DeployNft
    | BatchDeployNfts
    | ChangeCollectionAdmin;

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToNftCollection.fromSlice(in.body);

    match (msg) {
        // MINT one new NFT (admin-only).
        DeployNft => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress)
                throw ERROR_NOT_FROM_ADMIN;
            assert (msg.itemIndex <= storage.nextItemIndex)
                throw ERROR_INVALID_ITEM_INDEX;

            val isLast = msg.itemIndex == storage.nextItemIndex;
            deployNftItem(
                msg.itemIndex,
                storage.nftItemCode,
                msg.attachGrams,
                msg.initParams,
            );
            if (isLast) {
                storage.nextItemIndex += 1;
                storage.save();
            }
        }

        // MINT many NFTs in one message (admin-only).
        BatchDeployNfts => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress)
                throw ERROR_NOT_FROM_ADMIN;

            var counter = 0;
            var r = msg.deployList.findFirst();
            while (r.isFound) {
                counter += 1;
                // due to limits of action list size
                assert (counter < 250) throw ERROR_BATCH_LIMIT_EXCEEDED;

                val itemIndex = r.getKey();
                assert (itemIndex <= storage.nextItemIndex)
                    throw ERROR_NOT_FROM_ADMIN + counter;

                val dictItem = r.loadValue();
                deployNftItem(
                    itemIndex,
                    storage.nftItemCode,
                    dictItem.attachGrams,
                    dictItem.initParams,
                );

                if (itemIndex == storage.nextItemIndex) {
                    storage.nextItemIndex += 1;
                }
                r = msg.deployList.iterateNext(r);
            }
            storage.save();
        }

        // Transfer admin rights (mint permission) to a new address.
        ChangeCollectionAdmin => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress)
                throw ERROR_NOT_FROM_ADMIN;
            storage.adminAddress = msg.newAdminAddress;
            storage.save();
        }

        else => {
            // ignore empty messages, "wrong opcode" for others
            assert (in.body.isEmpty()) throw 0xFFFF;
        }
    }
}

struct CollectionDataReply {
    nextItemIndex: int
    collectionMetadata: cell
    adminAddress: address
}

// TEP-64 offchain metadata format wrapper used by TEP-62.
struct (0x01) OffchainMetadataReply {
    string: SnakeString
}

get fun get_collection_data(): CollectionDataReply {
    val storage = lazy NftCollectionStorage.load();
    val content = lazy storage.content.load();

    return {
        nextItemIndex: storage.nextItemIndex,
        collectionMetadata: content.collectionMetadata,
        adminAddress: storage.adminAddress,
    }
}

get fun get_nft_address_by_index(itemIndex: int): address {
    val storage = lazy NftCollectionStorage.load();
    val nftDeployed = calcDeployedNftItem(
        itemIndex as uint64,
        contract.getAddress(),
        storage.nftItemCode,
    );
    return nftDeployed.calculateAddress();
}

get fun get_nft_content(
    itemIndex: int,
    individualNftContent: Cell<SnakeString>,
): Cell<OffchainMetadataReply> {
    val storage = lazy NftCollectionStorage.load();
    val content = lazy storage.content.load();

    return OffchainMetadataReply {
        string: beginCell()
            // assume it's short (no refs)
            .storeSlice(content.commonContent.load())
            // so, it's the first ref (snake encoding)
            .storeRef(individualNftContent)
            .endCell()
            .beginParse(),
    }.toCell();
}

// Error codes used by the NFT item/collection contracts.
// Values follow the educational reference implementations where possible.

const ERROR_NOT_FROM_ADMIN = 401;
const ERROR_NOT_FROM_OWNER = 401;
const ERROR_NOT_FROM_COLLECTION = 405;

const ERROR_BATCH_LIMIT_EXCEEDED = 399;
const ERROR_INVALID_ITEM_INDEX = 402;
const ERROR_INCORRECT_FORWARD_PAYLOAD = 708;
const ERROR_INVALID_WORKCHAIN = 333;
const ERROR_TOO_SMALL_REST_AMOUNT = 402;

// Raised when the attached TON is insufficient to cover royalty + forwarding/gas bounds.
const ERROR_NOT_ENOUGH_ATTACHED_TON_FOR_ROYALTY = 403;

// Storage layouts for the TEP-62 NFT collection + royalty-enabled NFT item.
//
// In TON, a contract's persistent state ("storage") is just a `cell` — a
// binary blob. Tolk's `struct` + `.toCell()` / `.fromCell()` let us treat
// that blob as a typed object instead of hand-packing bits ourselves.

// SnakeString describes a (potentially long) string inside a cell.
// Short strings are stored as-is, long strings are stored in nested refs
// ("snake"-shaped, hence the name) so they can exceed one cell's ~1023 bits.
type SnakeString = slice;

fun SnakeString.unpackFromSlice(mutate s: slice) {
    // In the original reference implementation, the whole remaining slice is returned.
    // We keep the behavior but skip extra reference-count validations.
    val snakeRemainder = s;
    s = createEmptySlice(); // no more left to read
    return snakeRemainder;
}

fun SnakeString.packToBuilder(self, mutate b: builder) {
    b.storeSlice(self);
}

// Content of the collection itself (its metadata JSON + a prefix shared by
// every NFT's own metadata URI).
struct CollectionContent {
    collectionMetadata: cell
    commonContent: Cell<SnakeString>
}

// ---- Collection contract storage ----
// One collection contract manages many NFT items. It only needs to
// remember who's allowed to mint, how many items exist so far, its own
// metadata, and the code every new NFT item should be deployed with.
struct NftCollectionStorage {
    adminAddress: address   // only this address can mint new NFTs
    nextItemIndex: uint64   // index to use for the next minted NFT (0, 1, 2, ...)
    content: Cell<CollectionContent>
    nftItemCode: cell       // compiled code every NFT item contract is deployed with
}

// ---- NFT item contract storage ----
// Each individual NFT is its own tiny contract. It only needs to know
// which item/collection it is, who owns it right now, its metadata, and
// where the 2% transfer royalty should be paid.
struct NftItemStorage {
    itemIndex: uint64
    collectionAddress: address
    ownerAddress: address
    content: Cell<SnakeString>

    // Address that receives the 2% royalty every time this NFT is transferred.
    royaltyAddress: address
}

// Before the collection deploys an item, the item contract only knows its
// own index and its parent collection — nothing else exists yet.
struct NftItemStorageNotInitialized {
    itemIndex: uint64
    collectionAddress: address
}

fun NftCollectionStorage.load() {
    return NftCollectionStorage.fromCell(contract.getData());
}

fun NftCollectionStorage.save(self) {
    contract.setData(self.toCell());
}

fun NftItemStorage.save(self) {
    contract.setData(self.toCell());
}

// An NFT item contract's storage cell is either "not initialized yet"
// (just deployed, waiting for its first message from the collection) or
// "initialized" (has an owner, content, royalty address). We tell the two
// apart by checking whether the cell has any reference cells attached yet.
struct NftItemStorageMaybeNotInitialized {
    contractData: slice
}

fun NftItemStorageMaybeNotInitialized.isInitialized(self): bool {
    return self.contractData.remainingRefsCount() != 0;
}

fun NftItemStorageMaybeNotInitialized.parseNotInitialized(self) {
    return NftItemStorageNotInitialized.fromSlice(self.contractData);
}

fun NftItemStorageMaybeNotInitialized.parseInitialized(self) {
    return NftItemStorage.fromSlice(self.contractData);
}

fun startLoadingNftItemStorage(): NftItemStorageMaybeNotInitialized {
    return {
        contractData: contract.getData().beginParse(),
    }
}

// Computes the on-chain address an NFT item with a given index *would*
// have, without needing that contract to exist yet. TON addresses are
// derived from (code + initial data), so this is fully deterministic —
// the collection and anyone else can predict it in advance.
fun calcDeployedNftItem(
    itemIndex: uint64,
    collectionAddress: address,
    nftItemCode: cell,
): AutoDeployAddress {
    val emptyNftItemStorage: NftItemStorageNotInitialized = {
        itemIndex,
        collectionAddress,
    };

    return {
        stateInit: {
            code: nftItemCode,
            data: emptyNftItemStorage.toCell(),
        },
    }
}

// Message layouts used by the TEP-62 NFT contracts.
//
// TON contracts talk to each other by sending messages, and a message body
// is just a cell that starts with a 32-bit "opcode" saying what kind of
// message it is, followed by whatever data that message needs. Each
// `struct (0x...)` below is one such message shape; the number in
// parentheses is its opcode.

import "storage";

// Sent by the collection to a freshly-deployed NFT item, to fill in its
// real data (owner, content, royalty address) for the first time.
struct NftItemInitAtDeployment {
    ownerAddress: address
    content: Cell<SnakeString>
    royaltyAddress: address
}

// ---- Messages the COLLECTION contract accepts ----

// "Mint one NFT." Only the collection's admin can send this.
struct (0x00000001) DeployNft {
    queryId: uint64
    itemIndex: uint64
    attachGrams: coins                       // TON forwarded to fund the new NFT contract
    initParams: Cell<NftItemInitAtDeployment>
}

// "Mint many NFTs in one message." Same idea as DeployNft, just batched.
struct (0x00000002) BatchDeployNfts {
    queryId: uint64
    deployList: map<uint64, BatchDeployDictItem>
}

struct BatchDeployDictItem {
    attachGrams: coins
    initParams: Cell<NftItemInitAtDeployment>
}

// "Hand admin rights to someone else."
struct (0x00000003) ChangeCollectionAdmin {
    queryId: uint64
    newAdminAddress: address
}

// ---- Messages the ITEM (individual NFT) contract accepts ----

// TEP-62 standard: "Transfer this NFT to a new owner." Only the current
// owner may send this. This is also what triggers the 2% royalty payout.
struct (0x5fcc3d14) Transfer {
    queryId: uint64
    newOwnerAddress: address
    // If null => don't send excess TON back.
    sendExcessesTo: address?
    // Optional application data (not used by this contract).
    customPayload: dict
    // TON forwarded to the new owner as part of the "you now own this" notification.
    forwardGrams: coins
    // Remaining bits/refs forwarded to the new owner payload.
    forwardPayload: RemainingBitsAndRefs
}

// Sent by the item TO the new owner, right after a transfer completes —
// lets the new owner's wallet/dApp know "you now own this NFT".
struct (0x05138d91) NotificationForNewOwner {
    queryId: uint64
    oldOwnerAddress: address
    payload: RemainingBitsAndRefs
}

// Sent back to whoever paid for the transfer, refunding any TON that
// wasn't needed for gas/royalty/forwarding.
struct (0xd53276db) ReturnExcessesBack {
    queryId: uint64
}

// "Tell me your index and collection address." Read-only-style request,
// answered by ResponseStaticData below.
struct (0x2fcb26a2) RequestStaticData {
    queryId: uint64
}

struct (0x8b771735) ResponseStaticData {
    queryId: uint64
    itemIndex: uint256
    collectionAddress: address
}

// Sent to the royalty address whenever a transfer pays out its 2% cut.
// (There's no official TEP for "royalty on transfer" — this is just a
// deterministic message body so the payment is easy to recognize on-chain.)
struct (0x44445555) RoyaltyPaid {
    queryId: uint64
}
